// Bundles the approved, versioned coach scripts from content/ into the Core
// API (T-VOC-07, closed-script voice gateway, FR-VOC-05). Runs before every
// build and typecheck, so the deployed functions always carry the scripts
// that are in the repo; the generated file is not committed.
//
// Only ids, versions, review status and text are copied. Whether a line may
// be spoken is decided at request time by src/voice/scripts.ts.
import { readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const content = join(here, '..', '..', '..', 'content');
const out = join(here, '..', 'src', 'voice', 'scripts.generated.ts');

const read = (p) => JSON.parse(readFileSync(p, 'utf8'));

const momentsDir = join(content, 'coach', 'moments');
const moments = {};
for (const f of readdirSync(momentsDir).filter((f) => f.endsWith('.json')).sort()) {
  const t = read(join(momentsDir, f));
  const file = f.replace(/\.json$/, '');
  moments[file] = {
    version: t.version,
    review_status: t.review_status,
    variants: Object.fromEntries(t.variants.map((v) => [v.id, v.text])),
  };
}

const catalog = read(join(content, 'routine', 'catalog.json'));
const routineLines = {};
const spokenNames = {};
for (const a of catalog.activities) {
  spokenNames[a.id] = a.spoken_name;
  for (const l of a.lines) routineLines[`${a.id}.${l.id}`] = l.text;
}
for (const l of catalog.custom_lines) routineLines[`custom.${l.id}`] = l.text;

const bundle = {
  moments,
  routine: {
    version: catalog.version,
    review_status: catalog.review_status,
    lines: routineLines,
    spoken_names: spokenNames,
  },
};

writeFileSync(
  out,
  '// Generated by scripts/bundle-scripts.mjs from content/. Do not edit.\n' +
    "import type { ScriptBundle } from './scripts.js';\n\n" +
    `export const bundledScripts: ScriptBundle = ${JSON.stringify(bundle, null, 2)};\n`,
);
console.log(`bundled ${Object.keys(moments).length} moment files and ${Object.keys(routineLines).length} routine lines`);
